mapper.select:

select coalesce(sum(ep.position_sec), 0) 
from episode_progress ep 
join episodes e on e.id = ep.episode_id 
where ep.user_id = #{userId} 
  and ep.updated_at >= #{since} 
  and e.episode_number >= 4

